@users_bp.route("/<int:user_id>/orders", methods=["GET"])
@require_auth
def user_orders(user_id: int):
    """List a user's orders."""
    session = get_session()
    orders = session.query(Order).filter(Order.user_id == user_id).all()
    return jsonify([o.to_dict() for o in orders])

